import numpy as np

def solve():
    # States are (u, v, w)
    # x, y, z in 0..9
    # u=x+y, v=y+z, w=z+x
    states = []
    for x in range(10):
        for y in range(10):
            for z in range(10):
                u = x + y
                v = y + z
                w = z + x
                states.append((u, v, w))

    num_states = len(states)

    # Questions are (A, B, C)
    questions = []
    for a in range(10):
        for b in range(10):
            for c in range(10):
                A = a + b
                B = b + c
                C = c + a
                questions.append((A, B, C))

    num_questions = len(questions)

    # For each question, calculate the result for all states
    results = np.zeros((num_questions, num_states), dtype=int)
    for q_idx, (A, B, C) in enumerate(questions):
        for s_idx, (u, v, w) in enumerate(states):
            results[q_idx, s_idx] = abs(u - A) + abs(v - B) + abs(w - C)

    # Check if any single question is enough
    for q_idx in range(num_questions):
        if len(np.unique(results[q_idx])) == num_states:
            return 1

    # question_groups[q_idx] is a list of groups of state indices
    question_groups = []
    for q_idx in range(num_questions):
        res = results[q_idx]
        groups = {}
        for s_idx, val in enumerate(res):
            if val not in groups:
                groups[val] = []
            groups[val].append(s_idx)
        question_groups.append(list(groups.values()))

    # Optimization: only keep questions that are "useful".
    # A question q1 is "less useful" than q2 if every group in q1 is a refinement of q2.
    # That's not easy to check. Let's just try to find q1, q2.

    # To speed up, let's only check a subset of questions if needed.
    # But let's try the full search first.

    for q1_idx in range(num_questions):
        groups1 = question_groups[q1_idx]
        for q2_idx in range(q1_idx + 1, num_questions):
            groups2 = question_groups[q2_idx]

            possible = True
            # Condition: for all G in groups1, no two indices in G share the same result in q2
            # Let's pre-calculate the result for each state for question q2
            res_q2 = results[q2_idx]
            for G in groups1:
                # For each G, check if all results in q2 are unique
                # This is faster than a set:
                # We can use a local array or a small set.
                seen = set()
                for s_idx in G:
                    val = res_q2[s_idx]
                    if val in seen:
                        possible = False
                        break
                    seen.add(val)
                if not possible:
                    break

            if possible:
                return 2

    return 3

