            for i in range(len(G)):
                for j in range(i + 1, len(G)):
                    q_conflicts.append((G[i], G[j]))
        conflicts.append(q_conflicts)

    # Now for each q1, we need a q2 that distinguishes all (i, j) in conflicts[q1].
    # This means results[q2, i] != results[q2, j] for all (i, j) in conflicts[q1].

