    # x, y, z in 0..9
    # u=x+y, v=y+z, w=z+x
    states = []
    for x in range(10):
        for y in range(10):
            for z in range(10):
                u = x + y
                v = y + z
                w = z + x
                states.append((u, v, w))

    num_states = len(states)

    # Questions are (A, B, C)
    questions = []
    for a in range(10):
        for b in range(10):
            for c in range(10):
                A = a + b
                B = b + c
                C = c + a
                questions.append((A, B, C))

    num_questions = len(questions)

    results = np.zeros((num_questions, num_states), dtype=int)
    for q_idx, (A, B, C) in enumerate(questions):
        for s_idx, (u, v, w) in enumerate(states):
            results[q_idx, s_idx] = abs(u - A) + abs(v - B) + abs(w - C)

    # Check if any single question is enough
    for q_idx in range(num_questions):
        if len(np.unique(results[q_idx])) == num_states:
            return 1

    question_groups = []
    for q_idx in range(num_questions):
        res = results[q_idx]
        groups = {}
        for s_idx, val in enumerate(res):
            if val not in groups:
                groups[val] = []
            groups[val].append(s_idx)
        question_groups.append(list(groups.values()))

    # Sort questions by the number of groups they produce
    indexed_questions = sorted(range(num_questions), key=lambda q: len(question_groups[q]), reverse=True)

    # Check pairs
    for i in range(len(indexed_questions)):
        q1_idx = indexed_questions[i]
        groups1 = question_groups[q1_idx]

        for j in range(i + 1, len(indexed_questions)):
            q2_idx = indexed_questions[j]
            res_q2 = results[q2_idx]

            possible = True
            for G in groups1:
                # We can't use np.unique for a list G of state indices.
                # Wait, res_q2[G] is a numpy array of results for those indices.
                if len(np.unique(res_q2[G])) != len(G):
                    possible = False
                    break
            if possible:
                return 2

    return 3

print(solve())

